package kik.qa;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import java.io.*;import java.lang.reflect.*;import java.util.*;import java.util.concurrent.Callable;import java.util.function.BooleanSupplier;import org.json.*;import kik.i18n.*;
/** Measures actual native screen readiness; all playback belongs to a disposable profile. */
public final class LoadingAudit extends Instrumentation {
 Context c;String original,qa;volatile Activity current;Bundle args;JSONArray samples=new JSONArray();boolean passed=true;List<Activity> activities=new ArrayList<>();
 @Override public void onCreate(Bundle b){super.onCreate(b);args=b;start();}
 Object field(Object o,String n){try{Field f=o.getClass().getDeclaredField(n);f.setAccessible(true);return f.get(o);}catch(Exception e){throw new RuntimeException(e);}}
 <T>T ui(Callable<T> f){Object[] out=new Object[2];runOnMainSync(()->{try{out[0]=f.call();}catch(Throwable t){out[1]=t;}});if(out[1]!=null)throw new RuntimeException((Throwable)out[1]);return (T)out[0];}
 boolean await(BooleanSupplier f,long ms){long end=SystemClock.elapsedRealtime()+ms;while(SystemClock.elapsedRealtime()<end){if(f.getAsBoolean())return true;SystemClock.sleep(25);}return false;}
 Activity launch(Class<? extends Activity> type,Intent extras){Intent i=new Intent(c,type).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);if(extras!=null)i.putExtras(extras);Activity a=startActivitySync(i);activities.add(a);return a;}
 void sample(String name,long start,boolean ok)throws Exception{long ms=SystemClock.elapsedRealtime()-start;samples.put(new JSONObject().put("name",name).put("ms",ms).put("passed",ok));Bundle b=new Bundle();b.putString("stream",name+" = "+ms+"ms passed="+ok+"\n");sendStatus(0,b);if(!ok)throw new AssertionError(name);}
 @Override public void onStart(){c=getTargetContext();original=ProfileStore.current(c);String list=c.getSharedPreferences("kik_profiles",0).getString("list","[]");
 ((Application)c.getApplicationContext()).registerActivityLifecycleCallbacks(new Application.ActivityLifecycleCallbacks(){public void onActivityResumed(Activity a){current=a;}public void onActivityCreated(Activity a,Bundle b){}public void onActivityStarted(Activity a){}public void onActivityPaused(Activity a){}public void onActivityStopped(Activity a){}public void onActivitySaveInstanceState(Activity a,Bundle b){}public void onActivityDestroyed(Activity a){}});
 try{qa=ProfileStore.create(c,"QA Loading","audit").id;c.getSharedPreferences("kik_profiles",0).edit().putString("current",qa).commit();ProfileStore.picked=true;ProfileStore.completeTasteSetup(c,qa);
 long start=SystemClock.elapsedRealtime();Activity home=launch(HomeActivity.class,null);sample("cached_home_ready",start,await(()->ui(()->(Boolean)field(home,"loadedOnce")),60000));ui(()->{home.finish();return null;});
 long translationStart=SystemClock.elapsedRealtime();ui(()->DescTranslate.tr("Проверка мгновенной отрисовки описания "+System.nanoTime()));sample("main_thread_description_returns",translationStart,SystemClock.elapsedRealtime()-translationStart<250);
 String link="https://hdrezka.sh/series/drama/646-vo-vse-tyazhkie-2008.html";
 for(int i=0;i<3;i++){start=SystemClock.elapsedRealtime();Activity film=launch(FilmActivity.class,new Intent().putExtra("link",link).putExtra("title","Breaking Bad"));sample("film_ready_"+(i+1),start,await(()->ui(()->((View)field(film,"watch")).isEnabled()),60000));
 if(i==2){start=SystemClock.elapsedRealtime();ui(()->{((View)field(film,"watch")).performClick();return null;});sample("player_prepared",start,await(()->current instanceof KikPlayerActivity&&ui(()->(Boolean)field(current,"prepared")&&!(Boolean)field(current,"seeking")),60000));Activity player=current;long at=ui(()->(long)((VideoView)field(player,"video")).getCurrentPosition());SystemClock.sleep(2200);boolean advancing=ui(()->((VideoView)field(player,"video")).getCurrentPosition()>at+1500);sample("video_advances",SystemClock.elapsedRealtime(),advancing);ui(()->{player.finish();return null;});await(()->current==film,5000);}
 ui(()->{film.finish();return null;});}
 Site.Film a=Site.film(link);int count=a.episodes.size();a.episodes.clear();start=SystemClock.elapsedRealtime();Site.Film b=Site.film(link);sample("cached_film_copy",start,count>0&&b.episodes.size()==count&&a!=b);
 }catch(Throwable t){passed=false;try{samples.put(new JSONObject().put("error",t.toString()));}catch(Exception ignored){}}
 finally{try{ui(()->{for(Activity a:activities)if(!a.isDestroyed())a.finish();if(current!=null&&!current.isDestroyed())current.finish();return null;});SystemClock.sleep(600);c.getSharedPreferences("kik_profiles",0).edit().putString("current",original).commit();if(qa!=null)ProfileStore.delete(c,qa);c.getSharedPreferences("kik_profiles",0).edit().putString("list",list).putString("current",original).commit();File dir=new File(c.getExternalFilesDir(null),"design-audit");dir.mkdirs();try(FileOutputStream out=new FileOutputStream(new File(dir,"loading-"+args.getString("label","run")+".json"))){out.write(new JSONObject().put("passed",passed).put("samples",samples).toString(2).getBytes("UTF-8"));}}catch(Exception e){passed=false;}Bundle b=new Bundle();b.putString("stream","Loading audit passed="+passed);finish(passed?-1:0,b);}}
}
